-- Hall map positions are approximate points from Columbia Housing's embedded
-- location maps. The 538 W. 114th listing has no map point.
-- They are not surveyed entrance coordinates or indoor bathroom locations.
update public.buildings set entrance_lat = 40.807722, entrance_lng = -73.967213, entrance_notes = 'Columbia Housing lists the entrance at 605 W. 115th Street. Map position is approximate; the approach has not been field checked.' where id = '11111111-1111-4111-8111-111111111111';
update public.buildings set entrance_lat = 40.806280, entrance_lng = -73.966607, entrance_notes = 'Columbia Housing lists the entrance at West 114th Street and Broadway. Map position is approximate; the approach has not been field checked.' where id = '22222222-2222-4222-8222-222222222222';
update public.buildings set entrance_lat = 40.807423, entrance_lng = -73.966182, entrance_notes = 'Columbia Housing lists the entrance inside campus along South Lawns. Map position is approximate; the approach has not been field checked.' where id = '33333333-3333-4333-8333-333333333333';

on conflict (id) do nothing;

